contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address loggerA, address loggerB, bool statusA, bool statusB) public {
        vm.assume(loggerA != loggerB);
        vm.assume(owner != address(0));
        vm.assume(loggerA != address(0));
        vm.assume(loggerB != address(0));
        vm.assume(owner != loggerA && owner != loggerB);
        // Set contract owner to fuzzed owner and make first call as owner
        vm.prank(c.owner() == address(0) ? address(1) : c.owner());
        // We need to set the owner first; C doesn't expose a public owner, but onlyOwner is private.
        // We'll use a prank to the assumed owner as the contract has no public owner setter.
        // The contract expects msg.sender == _contractOwner; we can't set _contractOwner without a constructor.
        // The original contract C has no constructor, so _contractOwner = address(0).
        // onlyOwner will revert for any non-zero msg.sender.
        // To satisfy the rule, we must be the owner. So we prank the zero address.
        vm.prank(address(0));
        c.setApprovedLogger(loggerA, statusA);
        vm.prank(address(0));
        c.setApprovedLogger(loggerB, statusB);
        // If statusA is true, loggerA must be approved
        bool isApproved = c.approvedToLog(loggerA);
        assertTrue(statusA ? isApproved : !isApproved);
    }
}

