import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool _status) public {
        // Ensure the caller is the contract owner to rule out the normal 'Not owner' revert
        address owner = address(this);
        // The reference initially returns false for any address since approvedLoggers is empty
        bool beforeStatus = c.approvedToLog(owner);
        vm.prank(owner);
        // Use a try/catch to observe whether setApprovedLogger reverts
        bool success;
        try c.setApprovedLogger(owner, _status) {
            success = true;
        } catch {
            success = false;
        }
        bool afterStatus = c.approvedToLog(owner);

        // Property: if the call succeeded, the state MUST have changed from its previous value.
        // The reference succeeds (for the owner) and updates state, so (success => afterStatus != beforeStatus) holds.
        // The mutant's onlyOwner always reverts, so success is false and the implication is vacuously true for it?
        // No: the property is the stronger statement: after a call by the owner, approvedToLog(owner) MUST equal the set value.
        // The reference succeeds => afterStatus == _status.
        // The mutant reverts => afterStatus remains false, so for _status == true the property is violated.
        // We assert: if caller is owner, afterStatus must equal the requested _status (since onlyOwner should not revert for owner).
        assertTrue(afterStatus == _status);
    }
}

