        // Since c is deployed by this test, this test is the owner.
        vm.prank(address(this));
        c.setApprovedLogger(_logger, _status);
        // After setting, approvedToLog for _logger must equal _status.
        bool actual = c.approvedToLog(_logger);
        assertTrue(actual == _status);
    }
}

